     9	public class ArchiveCopyRule implements MessageRule {
    10	    private final String archiveEmail;
    11	    private long nextCopyId;
    12	
    13	    public ArchiveCopyRule(String archiveEmail, long nextCopyId) {
    14	        this.archiveEmail = archiveEmail;
    15	        this.nextCopyId = nextCopyId;
    16	    }
    17	
    18	    @Override
    19	    public List<Message> process(List<Message> messages) {
    20	        List<Message> result = new ArrayList<>();
    21	        for (Message message : messages) {
    22	            result.add(message);
    23	            if (message.status() == MessageStatus.SENT) {
    24	                result.add(createArchiveCopy(message));
    25	            }
    26	        }
    27	        return result;
    28	    }
    29	
    30	    private Message createArchiveCopy(Message original) {
    31	        return new Message(
    32	            nextCopyId++,
    33	            original.channel(),
    34	            archiveEmail,
    35	            "[Cópia] " + original.subject(),
    36	            original.body(),
    37	            MessageStatus.SENT
    38	        );
    39	    }
    40	}
