     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.Document;
     4	import com.pousadamarealta.domain.Message;
     5	import com.pousadamarealta.domain.MessageStatus;
     6	import com.pousadamarealta.messaging.MessageProcessor;
     7	
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	import java.util.concurrent.atomic.AtomicLong;
    11	
    12	public class MessageService {
    13	    private final List<Message> sentMessages = new ArrayList<>();
    14	    private final AtomicLong nextId = new AtomicLong(1);
    15	    private final MessageProcessor processor;
    16	
    17	    public MessageService(MessageProcessor processor) {
    18	        this.processor = processor;
    19	    }
    20	
    21	    public void sendConfirmationEmail(String to, String guestName, Document document) {
    22	        String subject = "Reserva confirmada - Pousada Maré Alta";
    23	        String body = buildConfirmationBody(guestName, document);
    24	        sendEmail(to, subject, body);
    25	    }
    26	
    27	    private String buildConfirmationBody(String guestName, Document document) {
    28	        StringBuilder sb = new StringBuilder();
    29	        sb.append("Olá, ").append(guestName).append("!\n\n");
    30	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    31	        sb.append(document.format()).append("\n\n");
    32	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
    33	        sb.append("Até breve!");
    34	        return sb.toString();
    35	    }
    36	
    37	    private void sendEmail(String to, String subject, String body) {
    38	        Message message = new Message(nextId.getAndIncrement(), "EMAIL", to, subject, body, MessageStatus.SENT);
    39	        List<Message> processed = processor.process(List.of(message));
    40	
    41	        synchronized (sentMessages) {
    42	            sentMessages.addAll(processed);
    43	
    44	            long maxId = processed.stream()
    45	                .mapToLong(Message::id)
    46	                .max()
    47	                .orElse(nextId.get() - 1);
    48	
    49	            if (maxId >= nextId.get()) {
    50	                nextId.set(maxId + 1);
    51	            }
    52	        }
    53	    }
    54	
    55	    public List<Message> getAllMessages() {
    56	        synchronized (sentMessages) {
    57	            return new ArrayList<>(sentMessages);
    58	        }
    59	    }
    60	}
