    13	import io.javalin.json.JavalinJackson;
    14	
    15	import java.util.ArrayList;
    16	import java.util.List;
    17	
    18	public class App {
    19	    public static void main(String[] args) {
    20	        int port = getPort();
    21	        boolean testMode = isTestMode();
    22	
    23	        RoomService roomService = new RoomService();
    24	        ReservationService reservationService = new ReservationService(roomService);
    25	
    26	        MessageProcessor messageProcessor = buildMessageProcessor(testMode);
    27	        MessageService messageService = new MessageService(messageProcessor);
    28	
    29	        ReportService reportService = new ReportService(reservationService, roomService);
    30	
    31	        Javalin app = createApp(roomService, reservationService, messageService, reportService);
    32	        app.start(port);
    33	    }
    34	
    35	    private static Javalin createApp(RoomService roomService, ReservationService reservationService,
    36	                                     MessageService messageService, ReportService reportService) {
    37	        ObjectMapper objectMapper = new ObjectMapper()
    38	            .registerModule(new JavaTimeModule())
    39	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    40	
    41	        Javalin app = Javalin.create(config -> {
    42	            config.jsonMapper(new JavalinJackson(objectMapper, false));
    43	        });
    44	
    45	        RoomController roomController = new RoomController(roomService);
    46	        ReservationController reservationController = new ReservationController(
    47	            reservationService, messageService);
    48	        MessageController messageController = new MessageController(messageService);
    49	        ReportController reportController = new ReportController(reportService);
    50	
    51	        app.get("/rooms", roomController::getAllRooms);
    52	        app.post("/reservations", reservationController::createReservation);
    53	        app.get("/reservations/{id}", reservationController::getReservation);
    54	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
    55	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
    56	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
    57	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    58	        app.get("/reservations/{id}/document", reservationController::getDocument);
    59	        app.get("/messages", messageController::getAllMessages);
    60	        app.get("/reports/occupancy", reportController::getOccupancyReport);
    61	        app.get("/reports/revenue", reportController::getRevenueReport);
    62	
    63	        return app;
    64	    }
    65	
    66	    private static MessageProcessor buildMessageProcessor(boolean testMode) {
    67	        List<MessageRule> rules = new ArrayList<>();
    68	
    69	        if (testMode) {
    70	            rules.add(new TestModeRule("testes@pousadamarealta.com.br"));
    71	        }
    72	
    73	        rules.add(new EmailValidationRule());
    74	
    75	        if (!testMode) {
    76	            rules.add(new ArchiveCopyRule("arquivo@pousadamarealta.com.br", 1000000));
    77	        }
    78	
    79	        return new MessageProcessor(rules);
    80	    }
    81	
    82	    private static int getPort() {
    83	        String portEnv = System.getenv("PORT");
    84	        if (portEnv != null && !portEnv.isEmpty()) {
    85	            try {
    86	                return Integer.parseInt(portEnv);
    87	            } catch (NumberFormatException e) {
    88	                return 7070;
    89	            }
    90	        }
    91	        return 7070;
    92	    }
    93	
    94	    private static boolean isTestMode() {
    95	        String testMode = System.getenv("HOTEL_TEST_MODE");
    96	        return "true".equalsIgnoreCase(testMode);
    97	    }
    98	}
